INSERT OR REPLACE INTO actividad VALUES('ACT-009','Lubricación del eje óptico y el husillo (tornillo de avance) del eje Z','SUB-003','Preventivo','Calendario: cada 3 meses. Intervalo de 3 meses aprobado por el responsable del proyecto (Diego A. Fernández) el 24-nov-2026; no es un intervalo publicado por ELEGOO. El manual F-01 solo dice "según sea necesario".',90,NULL,0,'Responsable de mantenimiento');
