INSERT OR REPLACE INTO actividad VALUES('ACT-021','Lubricación de los ejes ópticos X e Y','SUB-002','Preventivo','Calendario: cada 3 meses. Intervalo de 3 meses aprobado por el responsable del proyecto (Diego A. Fernández) el 24-nov-2026; no es un intervalo publicado por ELEGOO.',90,NULL,0,'Responsable de mantenimiento');
INSERT OR REPLACE INTO actividad VALUES('ACT-022','Limpieza e inspección de la caja de cambios del extrusor','SUB-005','Preventivo','Por condición y revisión trimestral junto con ACT-009 (PROPUESTA: E-10 no indica intervalo)',90,NULL,1,'Responsable de mantenimiento');
INSERT OR REPLACE INTO actividad VALUES('ACT-024','Inspección y engrase del módulo de alimentación automática (CANVAS)','SUB-007','Preventivo','Revisión trimestral junto con ACT-009 (PROPUESTA: E-10 no indica intervalo)',90,NULL,1,'Responsable de mantenimiento');
INSERT OR REPLACE INTO actividad VALUES('ACT-023','Tensado de las correas de los ejes X/Y','SUB-002','Correctivo','Por condición: ruido anormal, cambio de capas, saltos del motor o fallas de impresión; tras funcionamiento prolongado (F-07, E-10). Revisión visual en ACT-010',NULL,NULL,1,'Responsable de mantenimiento');
